function _t(k, fb){ try{ if(window.LBA_I18N) return window.LBA_I18N.t(k); }catch(e){} return fb; }
function _loc(){ try{ if(window.LBA_I18N) return window.LBA_I18N.locale(); }catch(e){} return 'fr-FR'; }
function fmt(n){return n.toLocaleString(_loc())+' €'}
function specsLine(v){
  const parts=[];
  if(v.annee) parts.push(v.annee);
  if(v.km) parts.push(v.km.toLocaleString(_loc())+' km'); else parts.push(_t('card.km.na','Km sur demande'));
  if(v.carburant) parts.push(v.carburant);
  if(v.boite) parts.push(v.boite);
  return parts.join(' · ');
}
function mailLink(v){
  const subject = 'KlarDrive - ' + v.marque + ' ' + v.modele + ' (ref ' + v.id + ')';
  const body = `${_t('wa.msg','Bonjour KlarDrive, je suis intéressé par')} ${v.marque} ${v.modele} (${fmt(v.prix)}) ref ${v.id}. ${_t('wa.msg.end','Est-il disponible ?')}`;
  return 'mailto:contact@klardrive.de?subject=' + encodeURIComponent(subject) + '&body=' + encodeURIComponent(body);
}
function priceHTML(v){
  if(v.prix_barre && v.prix_barre > v.prix){
    return `<div class="price"><s class="old-price">${fmt(v.prix_barre)}</s>${fmt(v.prix)}</div>`;
  }
  return `<div class="price">${fmt(v.prix)}</div>`;
}
function promoBadge(v){
  if(v.prix_barre && v.prix_barre > v.prix){
    var pct = Math.round((1 - v.prix/v.prix_barre)*100);
    return `<span class="badge promo">-${pct}%</span>`;
  }
  return '';
}
function fuelKey(f){ return {Essence:'filters.fuel.petrol',Diesel:'filters.fuel.diesel',Hybride:'filters.fuel.hybrid','Électrique':'filters.fuel.electric'}[f] || null; }
function gearKey(g){ return {Automatique:'gear.auto',Manuelle:'gear.man'}[g] || null; }
function vehSummary(v){
  var fk = v.carburant ? fuelKey(v.carburant) : null;
  var gk = v.boite ? gearKey(v.boite) : null;
  var data = {
    m: v.marque || '', mo: v.modele || '',
    ver: v.version ? ' (' + v.version + ')' : '',
    y: v.annee || _t('v.year.na', 'Année sur demande'),
    km: v.km ? v.km.toLocaleString(_loc()) + ' km' : _t('v.km.na', 'Kilométrage sur demande'),
    f: fk ? _t(fk, v.carburant) : (v.carburant || '—'),
    b: gk ? _t(gk, v.boite) : (v.boite || '—'),
    p: v.puissance || '—'
  };
  var tpl = _t('v.sum', '{m} {mo}{ver} – {y}, {km}, {f}, {b}, {p}.');
  return tpl.replace('{m}', data.m).replace('{mo}', data.mo).replace('{ver}', data.ver)
    .replace('{y}', data.y).replace('{km}', data.km).replace('{f}', data.f)
    .replace('{b}', data.b).replace('{p}', data.p);
}
function vehDesc(v){
  var l = 'fr'; try{ if(window.LBA_I18N) l = window.LBA_I18N.get(); }catch(e){}
  if(l === 'fr' && v.desc) return v.desc;
  return vehSummary(v);
}
function cardHTML(v){
  return `<div class="card veh-card" onclick="location.href='vehicule.html?id=${v.id}'" role="link" tabindex="0" onkeydown="if(event.key==='Enter')location.href='vehicule.html?id=${v.id}'"><img src="${v.img}" alt="${v.marque} ${v.modele}" loading="lazy">
  <div class="card-body"><span class="badge">${v.badge}</span><span class="badge blue">${v.cat}</span>${promoBadge(v)}
  <h3>${v.marque} ${v.modele}</h3><p class="meta">${specsLine(v)}</p>
  ${priceHTML(v)}
  <div class="veh-actions"><a class="btn btn-dark" href="vehicule.html?id=${v.id}">${_t('card.details','Détails')}</a><a class="btn btn-primary" href="${mailLink(v)}" onclick="event.stopPropagation()"><svg class="ic"><use href="#i-mail"/></svg>${_t('card.contact','Contacter')}</a></div>
  </div></div>`;
}
// Données live Supabase (repli statique intégré si hors ligne / non configuré)
(function(){
  function mapV(r){
    return {id:r.id, gallery:Array.isArray(r.gallery)?r.gallery:[], marque:r.marque||'', modele:r.modele||'',
      version:r.version||'', prix:Number(r.prix)||0,
       prix_barre:(r.prix_barre==null||r.prix_barre==='')?null:Number(r.prix_barre),
      annee:(r.annee==null||r.annee==='')?null:Number(r.annee),
      km:(r.km==null||r.km==='')?null:Number(r.km),
      carburant:r.carburant||'', boite:r.boite||'', puissance:r.puissance||'',
      img:r.img||'', cat:r.cat||'', badge:r.badge||'', desc:r.description||r.desc||''};
  }
  async function loadRemote(){
    try{
      if(!window.SB || !SB.configured()) return;
      var rows = await SB.select('vehicles', 'created_at.asc', 6000);
      if(!Array.isArray(rows) || !rows.length) return;
      var mapped = rows.map(mapV).filter(function(v){ return v.id && v.marque && v.modele; });
      if(!mapped.length) return;
      VEHICLES.length = 0;
      mapped.forEach(function(v){ VEHICLES.push(v); });
      document.dispatchEvent(new CustomEvent('lba:data'));
    }catch(e){}
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded', loadRemote);
  else loadRemote();
})();
